INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES
-- ============ 1. TUT-KOMPUTER7-001 : Google Docs (12 block) ============
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',1,jsonb_build_object('text',$txt$Masalah: Dokumen Berantakan Saat Dikerjakan Bareng-bareng$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','PARAGRAPH',2,jsonb_build_object('text',$txt$Mengerjakan tugas kelompok atau laporan kerja sering berubah jadi kekacauan: file Word dikirim bolak-balik lewat WhatsApp, muncul versi "final", "final revisi", sampai "final revisi beneran". Revisi teman tertimpa, ada yang mengedit file lama, dan tidak ada yang tahu mana versi terakhir yang benar. Masalah ini muncul karena setiap orang memegang salinan filenya masing-masing.$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',3,jsonb_build_object('text',$txt$Kenapa Google Docs Jadi Solusinya$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','PARAGRAPH',4,jsonb_build_object('text',$txt$Google Docs menyimpan satu dokumen di internet yang bisa dibuka dan diedit banyak orang dalam waktu bersamaan. Setiap perubahan tersimpan otomatis, setiap editor terlihat namanya lewat kursor berwarna, dan ada riwayat versi yang mencatat siapa mengubah apa dan kapan. Tidak ada lagi file ganda: semua orang bekerja di dokumen yang sama.$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',5,jsonb_build_object('text',$txt$Persiapan: Yang Perlu Disiapkan$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','LIST',6,jsonb_build_object('items',$txt$["Akun Google (Gmail) untuk pemilik dan semua kolaborator","Browser terbaru di laptop atau aplikasi Google Docs di HP","Koneksi internet yang stabil saat mengedit bersama","Daftar alamat email orang-orang yang akan diajak berkolaborasi","Tentukan dulu siapa yang boleh mengedit dan siapa yang hanya boleh membaca"]$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',7,jsonb_build_object('text',$txt$Langkah: Membuat dan Membagikan Dokumen$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','LIST',8,jsonb_build_object('items',$txt$["Buka docs.google.com lalu klik Dokumen kosong untuk membuat file baru","Beri judul dokumen yang jelas, misalnya Laporan Kelompok 3 - Final","Klik tombol Bagikan di kanan atas, lalu masukkan alamat email kolaborator","Atur peran tiap orang: Editor (bisa mengubah), Pemberi komentar (bisa memberi masukan), atau Pembaca (hanya melihat)","Aktifkan opsi Beri tahu orang agar mereka dapat email undangan","Untuk berbagi cepat, pilih Siapa pun yang memiliki link, lalu salin tautannya"]$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',9,jsonb_build_object('text',$txt$Fitur Kolaborasi: Komentar, Saran, dan Riwayat$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','PARAGRAPH',10,jsonb_build_object('text',$txt$Gunakan mode Saran (ikon pensil di toolbar) jika ingin mengusulkan perubahan tanpa langsung mengubah teks: usulan bisa diterima atau ditolak pemilik dokumen. Untuk diskusi, blok teks lalu tambah komentar, dan sebut nama dengan tanda @ agar orangnya dapat notifikasi. Jika terjadi kesalahan, buka File lalu Riwayat versi untuk melihat semua perubahan dan mengembalikan dokumen ke versi sebelumnya.$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','HEADING',11,jsonb_build_object('text',$txt$Risiko dan Hal yang Perlu Diwaspadai$txt$)),
(gen_random_uuid(),'e4666661-4661-4661-4661-466146614661','PARAGRAPH',12,jsonb_build_object('text',$txt$Jangan membagikan link "siapa pun" untuk dokumen berisi data pribadi karena tautan bisa tersebar. Editor yang ceroboh bisa menghapus bagian penting, jadi periksa riwayat versi secara berkala. Untuk kerja offline, aktifkan dulu mode offline di pengaturan agar dokumen tetap bisa dibuka tanpa internet. Penyelesaian: setelah dokumen selesai, cabut akses editor yang sudah tidak perlu, unduh salinan dalam format PDF sebagai arsip, dan simpan link dokumen di tempat yang mudah ditemukan.$txt$)),
-- ============ 2. TUT-KESEHATAN9-001 : Asam Urat (12 block) ============
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',1,jsonb_build_object('text',$txt$Masalah: Sendi Tiba-tiba Nyeri Hebat, Terutama di Jempol Kaki$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','PARAGRAPH',2,jsonb_build_object('text',$txt$Serangan asam urat biasanya datang mendadak, sering pada malam hari: sendi terasa sangat nyeri, membengkak, memerah, dan terasa panas saat disentuh. Jempol kaki adalah lokasi paling umum, tetapi bisa juga menyerang pergelangan kaki, lutut, atau jari tangan. Rasa nyerinya bisa begitu hebat sampai selimut yang menyentuh kaki pun terasa menyakitkan.$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',3,jsonb_build_object('text',$txt$Apa Itu Asam Urat? Ini Penjelasannya$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','PARAGRAPH',4,jsonb_build_object('text',$txt$Asam urat adalah zat sisa dari pemecahan purin, senyawa yang ada di dalam tubuh dan di banyak makanan. Normalnya asam urat dibuang lewat urine, tetapi jika kadarnya terlalu tinggi, ia mengkristal dan menumpuk di sendi sehingga menimbulkan peradangan. Secara umum kadar normalnya di bawah 7 mg/dL untuk pria dan di bawah 6 mg/dL untuk wanita. Faktor risikonya antara lain pola makan tinggi purin, obesitas, kurang minum air, dan riwayat keluarga.$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',5,jsonb_build_object('text',$txt$Persiapan: Catat Pola Makan dan Gejala$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','LIST',6,jsonb_build_object('items',$txt$["Catat semua makanan dan minuman selama satu minggu","Catat kapan nyeri muncul dan makanan apa yang dimakan sebelumnya","Timbang berat badan dan ukur lingkar perut sebagai data awal","Cari tahu apakah orang tua atau saudara punya riwayat asam urat","Siapkan catatan ini untuk dibawa saat konsultasi ke dokter"]$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',7,jsonb_build_object('text',$txt$Langkah: Pantangan Makanan Tinggi Purin$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','LIST',8,jsonb_build_object('items',$txt$["Jeroan: hati, ginjal, usus, otak, dan babat","Ikan sarden, makarel, teri, dan kerang-kerangan","Kaldu daging yang kental dan ekstrak daging","Daging merah dalam porsi besar dan terlalu sering","Alkohol terutama bir, serta minuman bersoda tinggi fruktosa","Batasi sayur tinggi purin seperti bayam, asparagus, dan kembang kol, tetapi tidak perlu dihindari total"]$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',9,jsonb_build_object('text',$txt$Makanan dan Kebiasaan yang Umumnya Membantu$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','LIST',10,jsonb_build_object('items',$txt$["Minum air putih 2 sampai 3 liter per hari untuk membantu membuang asam urat","Buah-buahan, terutama ceri yang dalam beberapa penelitian dikaitkan dengan penurunan risiko serangan","Susu dan yogurt rendah lemak","Kopi secukupnya bagi yang biasa minum kopi","Menurunkan berat badan secara bertahap jika berlebih, jangan diet ekstrem yang justru memicu serangan"]$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','HEADING',11,jsonb_build_object('text',$txt$Risiko: Jangan Mengobati Sendiri Sembarangan$txt$)),
(gen_random_uuid(),'e4666662-4662-4662-4662-466246624662','PARAGRAPH',12,jsonb_build_object('text',$txt$Artikel ini hanya informasi umum dan bukan pengganti nasihat medis. Segera konsultasi ke dokter jika nyeri sendi berulang, bengkak tidak kunjung reda, muncul benjolan di sekitar sendi (tofus), atau disertai demam. Jangan mengonsumsi obat pereda nyeri atau penurun asam urat tanpa resep dokter karena dosis dan jenisnya harus disesuaikan kondisi masing-masing. Penyelesaian: bawa catatan pola makan ke dokter, lakukan cek laboratorium berkala, dan jalani pola makan rendah purin secara konsisten.$txt$)),
-- ============ 3. EXP-ANTROPOLOGI6-001 : Minangkabau (10 block) ============
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','HEADING',1,jsonb_build_object('text',$txt$Siapa Orang Minangkabau?$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','PARAGRAPH',2,jsonb_build_object('text',$txt$Orang Minangkabau adalah suku bangsa yang berasal dari Sumatera Barat, dengan jumlah diperkirakan lebih dari delapan juta jiwa. Mereka berbahasa Minang, terkenal sebagai pedagang dan perantau ulung, dan memiliki sistem kekerabatan yang unik: matrilineal, garis keturunan yang dihitung dari pihak ibu.$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','HEADING',3,jsonb_build_object('text',$txt$Sistem Matrilineal Terbesar di Dunia$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','PARAGRAPH',4,jsonb_build_object('text',$txt$Minangkabau disebut sebagai masyarakat matrilineal terbesar di dunia. Artinya, nama suku dan harta pusaka diwariskan melalui garis perempuan: anak mengikuti suku ibunya, dan rumah serta tanah pusaka dikelola oleh kaum perempuan. Laki-laki dewasa berperan sebagai mamak, yaitu paman yang menjadi pemimpin dan penanggung jawab kaum keponakannya. Sistem ini menjaga agar harta pusaka tidak berpindah keluar dari kaum.$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','HEADING',5,jsonb_build_object('text',$txt$Rumah Gadang dan Legenda Tanduk Kerbau$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','PARAGRAPH',6,jsonb_build_object('text',$txt$Ikon Minangkabau yang paling dikenal adalah rumah gadang dengan atap melengkung runcing seperti tanduk kerbau, disebut gonjong. Menurut legenda, nama Minangkabau berasal dari kemenangan adu kerbau melawan utusan kerajaan Jawa: minang berarti menang dan kabau berarti kerbau. Rumah gadang bukan sekadar tempat tinggal, melainkan simbol martabat kaum yang dihuni bersama oleh keluarga besar perempuan.$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','HEADING',7,jsonb_build_object('text',$txt$Merantau: Tradisi Wajib Para Bujang$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','PARAGRAPH',8,jsonb_build_object('text',$txt$Dalam adat Minang, laki-laki dewasa diharapkan merantau: pergi meninggalkan kampung halaman untuk mencari ilmu, pengalaman, dan rezeki. Pepatahnya berbunyi, karatau madang di hulu, babuah babungo balun, marantau bujang dahulu, di rumah baguno balun: merantaulah dulu selagi bujang, karena di rumah belum berguna. Jejak perantau Minang terlihat dari warung nasi Padang yang ada di hampir setiap kota di Indonesia.$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','HEADING',9,jsonb_build_object('text',$txt$Adat Basandi Syarak, Syarak Basandi Kitabullah$txt$)),
(gen_random_uuid(),'e4666663-4663-4663-4663-466346634663','PARAGRAPH',10,jsonb_build_object('text',$txt$Falsafah hidup orang Minang dirangkum dalam kalimat adat basandi syarak, syarak basandi kitabullah: adat bersendikan ajaran Islam, dan ajaran Islam bersendikan Al-Quran. Ninik mamak menjaga adat, ulama menjaga agama, dan keduanya berjalan beriringan. Dari falsafah inilah lahir tokoh-tokoh besar Indonesia seperti Mohammad Hatta, Sutan Sjahrir, dan Buya Hamka. Minangkabau membuktikan bahwa adat dan agama bisa saling menguatkan, bukan saling meniadakan.$txt$)),
-- ============ 4. EXP-FISIKA9-001 : Tekanan (10 block) ============
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','HEADING',1,jsonb_build_object('text',$txt$Apa Itu Tekanan?$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','PARAGRAPH',2,jsonb_build_object('text',$txt$Tekanan adalah besarnya gaya yang bekerja pada setiap satuan luas permukaan, dirumuskan P sama dengan F dibagi A. Satuannya dalam SI adalah Pascal (Pa), yaitu satu newton per meter persegi. Contoh sederhananya: sepatu hak runcing lebih mudah menancap ke tanah lunak dibanding sepatu datar, karena gaya berat badan yang sama terpusat pada luas yang jauh lebih kecil.$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','HEADING',3,jsonb_build_object('text',$txt$Tekanan pada Ban Kendaraan$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','PARAGRAPH',4,jsonb_build_object('text',$txt$Ban mobil umumnya diisi udara bertekanan sekitar 28 sampai 35 psi, sesuai anjuran pabrikan yang tertera di pintu pengemudi. Ban yang kurang angin membuat permukaan ban menempel lebih lebar ke jalan: akibatnya bensin lebih boros, ban cepat aus di tepi, dan mobil lebih sulit dikendalikan. Sebaliknya ban yang terlalu keras membuat bantingan tidak nyaman dan daya cengkeram berkurang. Karena itu tekanan ban sebaiknya dicek rutin saat ban dalam keadaan dingin.$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','HEADING',5,jsonb_build_object('text',$txt$Tekanan Udara dan Atmosfer$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','PARAGRAPH',6,jsonb_build_object('text',$txt$Kita hidup di dasar lautan udara yang menekan tubuh dari segala arah dengan tekanan sekitar 1 atmosfer atau 101.325 Pascal di permukaan laut. Kita tidak merasakannya karena tekanan di dalam tubuh menyeimbanginya. Semakin tinggi suatu tempat, semakin tipis udara dan semakin rendah tekanannya: inilah sebabnya telinga berdenging saat naik gunung atau pesawat lepas landas, karena gendang telinga menyesuaikan perbedaan tekanan.$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','HEADING',7,jsonb_build_object('text',$txt$Tekanan di Dalam Air$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','PARAGRAPH',8,jsonb_build_object('text',$txt$Air jauh lebih berat daripada udara, sehingga tekanan bertambah cepat di bawah permukaan: setiap turun 10 meter, tekanan bertambah sekitar 1 atmosfer. Penyelam di kedalaman 20 meter menanggung tekanan 3 atmosfer sekaligus. Inilah alasan penyelam harus naik perlahan agar tubuh sempat menyesuaikan, dan kapal selam dibuat dari baja tebal agar tidak remuk oleh tekanan air laut dalam.$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','HEADING',9,jsonb_build_object('text',$txt$Manfaat Tekanan dalam Kehidupan Sehari-hari$txt$)),
(gen_random_uuid(),'e4666664-4664-4664-4664-466446644664','PARAGRAPH',10,jsonb_build_object('text',$txt$Prinsip tekanan dipakai di mana-mana: panci presto memasak lebih cepat karena tekanan tinggi menaikkan titik didih air; dongkrak hidrolik mengangkat mobil berat berkat hukum Pascal yang meneruskan tekanan ke segala arah; suntikan dokter bekerja karena tekanan jari pada pengisap yang kecil menghasilkan dorongan kuat pada cairan. Dari ban motor sampai atmosfer Bumi, tekanan adalah konsep fisika yang diam-diam mengatur banyak hal di sekitar kita.$txt$)),
-- ============ 5. SCH-SMP-ING4-001 : Comparative (12 block) ============
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',1,jsonb_build_object('text',$txt$Tujuan Pembelajaran$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','PARAGRAPH',2,jsonb_build_object('text',$txt$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) memahami pengertian comparative adjective, (2) membentuk comparative dari kata sifat pendek dan kata sifat panjang dengan benar, (3) membuat kalimat perbandingan dua hal dalam bahasa Inggris, dan (4) menghindari kesalahan umum seperti double comparative.$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',3,jsonb_build_object('text',$txt$Apa Itu Comparative Adjective?$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','PARAGRAPH',4,jsonb_build_object('text',$txt$Comparative adjective dipakai untuk membandingkan dua benda, orang, atau hal. Cirinya selalu diikuti kata than yang berarti daripada. Contoh: My house is bigger than yours (Rumahku lebih besar daripada rumahmu). Bandingkan dengan positive (as big as) yang menyatakan sama, dan superlative (the biggest) yang menyatakan paling di antara banyak.$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',5,jsonb_build_object('text',$txt$Rumus 1: Kata Sifat Pendek (Satu Suku Kata)$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','LIST',6,jsonb_build_object('items',$txt$["Pola umum: adjective + -er + than. Contoh: tall menjadi taller than, fast menjadi faster than","Kata berakhiran konsonan-vokal-konsonan: konsonan akhir digandakan. Contoh: big menjadi bigger than, hot menjadi hotter than","Kata berakhiran huruf y: y berubah menjadi i lalu tambah -er. Contoh: happy menjadi happier than, easy menjadi easier than","Kata berakhiran huruf e: langsung tambah -r. Contoh: large menjadi larger than, nice menjadi nicer than"]$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',7,jsonb_build_object('text',$txt$Rumus 2: Kata Sifat Panjang (Dua Suku Kata atau Lebih)$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','PARAGRAPH',8,jsonb_build_object('text',$txt$Untuk kata sifat yang panjang, polanya adalah more + adjective + than, tanpa mengubah kata sifatnya. Contoh: expensive menjadi more expensive than, beautiful menjadi more beautiful than, interesting menjadi more interesting than. Ada bentuk tidak beraturan yang harus dihafal: good menjadi better than, bad menjadi worse than, far menjadi farther than, dan little menjadi less than.$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',9,jsonb_build_object('text',$txt$Contoh Kalimat$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','LIST',10,jsonb_build_object('items',$txt$["An elephant is bigger than a horse. (Gajah lebih besar daripada kuda.)","This book is more interesting than that one. (Buku ini lebih menarik daripada yang itu.)","My sister is happier than me today. (Kakakku lebih bahagia daripada aku hari ini.)","A motorcycle is faster than a bicycle. (Sepeda motor lebih cepat daripada sepeda.)","Your idea is better than mine. (Idemu lebih bagus daripada ideku.)"]$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','HEADING',11,jsonb_build_object('text',$txt$Latihan Soal$txt$)),
(gen_random_uuid(),'e4666665-4665-4665-4665-466546654665','LIST',12,jsonb_build_object('items',$txt$["Lengkapi: A car is ___ (fast) than a bus. | Kunci: faster","Lengkapi: This movie is ___ (good) than the last one. | Kunci: better","Benarkan kalimat ini: She is more taller than her brother. | Kunci: She is taller than her brother. (tidak boleh more + -er sekaligus)","Terjemahkan: Tas ini lebih murah daripada tas itu. | Kunci: This bag is cheaper than that one."]$txt$)),
-- ============ 6. SCH-SD-MAT11-001 : Skala (12 block) ============
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',1,jsonb_build_object('text',$txt$Tujuan Pembelajaran$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','PARAGRAPH',2,jsonb_build_object('text',$txt$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian skala, (2) menentukan jarak sebenarnya dari jarak pada peta, (3) menentukan jarak pada peta atau denah dari jarak sebenarnya, dan (4) menyelesaikan soal cerita yang berkaitan dengan skala.$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',3,jsonb_build_object('text',$txt$Apa Itu Skala?$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','PARAGRAPH',4,jsonb_build_object('text',$txt$Skala adalah perbandingan antara jarak pada gambar (peta atau denah) dengan jarak sebenarnya di lapangan. Skala ditulis misalnya 1 : 100.000, artinya setiap 1 cm pada peta mewakili 100.000 cm atau 1 km jarak sebenarnya. Tanpa skala, peta tidak bisa dipakai untuk mengukur jarak sungguhan.$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',5,jsonb_build_object('text',$txt$Rumus Segitiga Skala$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','PARAGRAPH',6,jsonb_build_object('text',$txt$Ada tiga rumus yang saling berkaitan dan mudah diingat dengan segitiga JP-S-JS. Jarak pada peta sama dengan skala dikali jarak sebenarnya (JP = S x JS). Jarak sebenarnya sama dengan jarak pada peta dibagi skala (JS = JP : S). Skala sama dengan jarak pada peta dibagi jarak sebenarnya (S = JP : JS). Ingat: samakan dulu satuannya, biasanya ke sentimeter, sebelum menghitung.$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',7,jsonb_build_object('text',$txt$Contoh 1: Mencari Jarak Sebenarnya$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','PARAGRAPH',8,jsonb_build_object('text',$txt$Jarak kota A ke kota B pada peta adalah 5 cm. Skala peta 1 : 200.000. Berapa jarak sebenarnya? Jawab: JS = JP : S = 5 x 200.000 = 1.000.000 cm. Ubah ke kilometer: 1.000.000 cm = 10 km. Jadi jarak sebenarnya kedua kota adalah 10 km.$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',9,jsonb_build_object('text',$txt$Contoh 2: Mencari Jarak pada Peta$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','PARAGRAPH',10,jsonb_build_object('text',$txt$Jarak sebenarnya rumah Andi ke sekolah adalah 15 km. Jika digambar dengan skala 1 : 500.000, berapa cm jarak pada gambar? Jawab: ubah dulu 15 km = 1.500.000 cm. JP = S x JS = 1.500.000 : 500.000 = 3 cm. Jadi jarak pada gambar adalah 3 cm.$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','HEADING',11,jsonb_build_object('text',$txt$Latihan Soal$txt$)),
(gen_random_uuid(),'e4666666-4666-4666-4666-466646664666','LIST',12,jsonb_build_object('items',$txt$["Jarak pada denah 4 cm, skala 1 : 100. Berapa jarak sebenarnya dalam meter? | Kunci: 4 x 100 = 400 cm = 4 meter","Jarak sebenarnya 6 km digambar dengan skala 1 : 300.000. Berapa cm jarak pada peta? | Kunci: 6 km = 600.000 cm; 600.000 : 300.000 = 2 cm","Jarak pada peta 8 cm mewakili jarak sebenarnya 16 km. Berapa skalanya? | Kunci: 16 km = 1.600.000 cm; 8 : 1.600.000 = 1 : 200.000"]$txt$))
